                       String responseJson, LocalDateTime createdAt) {
        jdbcTemplate.update(
                "INSERT INTO idempotency_record "
                        + "(scope, request_id, fingerprint, response_json, created_at) "
                        + "VALUES (?, ?, ?, ?, ?)",
                scope, requestId, fingerprint, responseJson, Timestamp.valueOf(createdAt));
    }
}

