                "INSERT INTO seed_batch (batch_no, crop_name, created_at) VALUES (?, '合成作物', ?)",
                batchNo, Timestamp.valueOf(now));
        Long id = jdbcTemplate.queryForObject(
                "SELECT id FROM seed_batch WHERE batch_no = ?", Long.class, batchNo);
        return id == null ? -1 : id;
    }
}

